def compute_existing_portfolios(apps, schema_editor):
    """Existing architects keep working as before (the new ``portfolio_exempt`` column
    defaults to True for them); just fill in whether their portfolio is already complete."""
    Profile = apps.get_model("architects", "ArchitectProfile")
    Project = apps.get_model("architects", "PortfolioProject")
    for profile in Profile.objects.exclude(kind="studio_employee"):
        req = settings.PORTFOLIO_REQUIREMENTS["studio" if profile.kind == "studio_owner" else "freelancer"]
        ready = (
            Project.objects.filter(architect=profile)
            .annotate(photos=Count("images")).filter(photos__gte=req["images"]).count()
        )
        profile.portfolio_complete = ready >= req["projects"]
        profile.save(update_fields=["portfolio_complete"])


